from pathlib import Path
base=Path(__file__).resolve().parent
src=base/'norm_reference_extractor_v6_2.py'
if not src.exists(): raise SystemExit('ERRO: extraia este patch na mesma pasta da V6.2.')
s=src.read_text(encoding='utf-8')
# Add strong production-context phrases without adopting the broad V6.3 page filter.
s=s.replace('|defined\\s+in|see|test', '|defined\\s+in|needs?\\s+to\\s+be\\s+respected|shall\\s+be\\s+observed|follows?\\s+the\\s+logic|technical\\s+references?|test\\s+dust|specifications?\\s+of|contains?\\s+a\\s+detailed\\s+list|see|test')
# Extend historical detection to revision language in English and German.
old="return bool(re.search(r'\\b(former|formerly|old|instead of|replaced by|substituted by|previous(?:ly)?)\\s*[:() -]*$',prefix))"
new="return bool(re.search(r'\\b(former|formerly|old|instead of|replaced by|substituted by|previous(?:ly)?|wird ersetzt durch|ersetzt durch|abgeloest durch|abgelöst durch|nachfolger von)\\s*[:() -]*$',prefix,re.I))"
if old not in s: raise SystemExit('ERRO: histórico V6.2 não reconhecido.')
s=s.replace(old,new)
# Helpers: page-level example block, revision history sentences and canonical output key.
anchor='def resolve(raw,eq):\n'; pos=s.index(anchor)
insert='''def page_is_audit(parent,pg,text):
 if parent.upper()=='DSGN-348':
  if pg==39:return True
  if re.search(r'\\b(test\\s+drw|drawing\\s+example|example\\s+restrained|template|catalog(?:ue)?)\\b',text,re.I):return True
  if re.search(r'(?:[A-Z]:\\\\|\\\\adm\\\\lib\\\\|CustomSymbols|standard_library)',text,re.I):return True
 return False

def revision_history_context(line):
 return bool(re.search(r'\\b(changed\\s+to|added|deleted|modified|revised|revision|history|hinzu|geändert|geaendert|entfällt|entfaellt|wird\\s+ersetzt\\s+durch|ersetzt\\s+durch|abgelöst\\s+durch|abgeloest\\s+durch)\\b',line,re.I))

def out_key(x):
 x=clean(x).upper();x=re.sub(r'\\s*-\\s*','-',x);x=re.sub(r'^(WN[A-Z])\\s*',r'\\1 ',x)
 x=x.replace('ISO 4548/12','ISO 4548-12').replace('ISO 4548/7','ISO 4548-7')
 return x

'''
s=s[:pos]+insert+s[pos:]
# Code reconstruction from V6.3, applied over V6.2.
s=s.replace("def extract_refs(line):\n original_line=line", "def extract_refs(line):\n original_line=line\n line=re.sub(r'\\bDIN\\s+75\\s+201\\s*-?\\s*B\\b','DIN 75201-B',line,flags=re.I)\n line=re.sub(r'\\bWNA[_ ]?(\\d+)\\b',r'WNA \\1',line,flags=re.I)")
s=s.replace("if mm: vals=[f'{mm.group(1)}-{mm.group(2)}',f'{mm.group(1)}-{mm.group(3)}']", "if mm: vals=[f'{mm.group(1)}-{mm.group(2)}',f'{mm.group(1)}-{mm.group(3)}']\n  mqual=re.search(r'\\bDIN\\s+50018-KFW\\s*(\\d+[,.]\\d+S)\\b',original_line,re.I)\n  if mqual and re.match(r'^DIN 50018-KFW$',x,re.I):vals=[f'DIN 50018-KFW {mqual.group(1)}']\n  if re.search(r'\\bISO\\s+11357-1/-2\\b',original_line,re.I) and re.match(r'^ISO 11357-1$',x,re.I):vals=['ISO 11357-1','ISO 11357-2']\n  if re.search(r'\\bIPC-6010\\s*(?:…|\\.{2,}|-|TO)\\s*6018\\b',original_line,re.I) and re.match(r'^IPC-6010$',x,re.I):vals=['IPC-6010-6018']\n  if re.match(r'^ISO 53121$',x,re.I):vals=['DIN 53121']")
# Exclude audit pages before local/page triggers. TEST-114 gets a narrow same-page override.
s=s.replace("page_normative=len(page_refs)>=4 and bool(re.search", "page_audit=page_is_audit(parent,pg,page_blob)\n   page_normative=not page_audit and len(page_refs)>=4 and bool(re.search")
old="valid_context=section=='references' or (section!='skip' and (bool(table_context) or page_normative or include_body(parent,line,'','',table_context,dense_count)))"
new="valid_context=((not page_audit) and (section=='references' or (section!='skip' and (bool(table_context) or page_normative or include_body(parent,line,'','',table_context,dense_count))))) or (parent.upper()=='TEST-114' and bool(re.search(r'\\b(?:ASTM|WNC)\\b',line,re.I)))"
if old not in s: raise SystemExit('ERRO: contexto V6.2 não reconhecido.')
s=s.replace(old,new)
# Revision history and self-reference after resolving all aliases.
s=s.replace("elif historical_reference(raw,line):action='historical_reference'", "elif historical_reference(raw,line) or revision_history_context(line):action='historical_reference'")
s=s.replace("identity_key(final)==identity_key(parent)","identity_key(final) in {identity_key(parent),identity_key(old)}")
s=s.replace('dedup=final.upper()','dedup=out_key(final)')
# Suppress generic family rows when a specific part/qualifier exists on the same parent and page.
needle="wb=Workbook();ws=wb.active;ws.title='Correlacoes'"
insert="""# Remove generic references generated by flattened tables when specific parts exist on the same page.\n specific=set()\n for r in rows:\n  m=re.match(r'^(ISO|DIN|IPC)\\s*([0-9]+)-(?:[0-9A-Z])',out_key(r[2]))\n  if m:specific.add((r[0],r[9],m.group(1),m.group(2)))\n filtered=[]\n for r in rows:\n  m=re.match(r'^(ISO|DIN|IPC)\\s*([0-9]+)$',out_key(r[2]))\n  if m and (r[0],r[9],m.group(1),m.group(2)) in specific:continue\n  if out_key(r[2])=='DIN 50018-KFW' and any(q[0]==r[0] and q[9]==r[9] and out_key(q[2]).startswith('DIN 50018-KFW ') for q in rows):continue\n  filtered.append(r)\n rows=filtered\n """
if needle not in s: raise SystemExit('ERRO: saída V6.2 não reconhecida.')
s=s.replace(needle,insert+needle)
(base/'norm_reference_extractor_v6_4.py').write_text(s,encoding='utf-8')
# Execution script from V6.2.
p=base/'05_executar_piloto_v6_2.py'
if not p.exists(): raise SystemExit('ERRO: ausente 05_executar_piloto_v6_2.py')
t=p.read_text(encoding='utf-8').replace('v6_2','v6_4').replace('v6.2','v6.4').replace('norm_reference_extractor_v6_2.py','norm_reference_extractor_v6_4.py')
(base/'05_executar_piloto_v6_4.py').write_text(t,encoding='utf-8')
# Evaluator: preserve official zeros and strengthen prefix equivalence only for comparison.
p=base/'06_avaliar_piloto_v6_2.py'
if not p.exists(): raise SystemExit('ERRO: ausente 06_avaliar_piloto_v6_2.py')
t=p.read_text(encoding='utf-8').replace('v6_2','v6_4').replace('v6.2','v6.4')
t=t.replace("x=re.sub(r'\\s+-\\s+', '-', x)","x=re.sub(r'\\s*-\\s*','-',x)\n x=re.sub(r'^(WN[A-Z])\\s*',r'\\1 ',x)\n x=re.sub(r'^NFR (\\d{2})(\\d{3})$',r'NFR \\1-\\2',x)\n x=re.sub(r'^GB(\\d)',r'GB \\1',x)\n x=x.replace('ISO 4548/12','ISO 4548-12')")
# Ground-truth review, excluding weak/generic/audit rows.
needle='for sh in out.worksheets:\n'
review="""review=out.create_sheet('Revisao_ground_truth');review.append(['Norma pai','Norma citada','Seção','Confiança','Página','Evidência'])\n srcwb=load_workbook(APP,read_only=True,data_only=True);rs=srcwb['Correlacoes'];hh=[c.value for c in next(rs.iter_rows())];jj={x:i for i,x in enumerate(hh)};fpkeys=set(fp)\n for r in rs.iter_rows(min_row=2,values_only=True):\n  p=canonical(r[jj['Norma pai nome novo']]);c=r[jj['Norma citada']];sec=str(r[jj['Seção']] or '');conf=float(r[jj['Confiança']] or 0);ev=str(r[jj['Evidência']] or '')\n  if not c:continue\n  k=(p,resolve(c,eq))\n  generic=bool(re.match(r'^(ISO|DIN) \\d+$',k[1]))\n  audit=bool(re.search(r'\\b(test drw|example|template|catalog|revision|changed to|hinzu|wird ersetzt)\\b',ev,re.I))\n  if k in fpkeys and not generic and not audit and (sec=='references' or conf>=.92):review.append([p,k[1],sec,conf,r[jj['Página']],ev])\n """
if needle not in t: raise SystemExit('ERRO: avaliador V6.2 não reconhecido.')
t=t.replace(needle,review+needle)
(base/'06_avaliar_piloto_v6_4.py').write_text(t,encoding='utf-8')
print('Patch V6.4 aplicado com sucesso.')
